// n8n Code node (JavaScript)
// Input: items from Gmail Trigger (like your JSON)
// Output fields: senderName, senderEmail, bodyText

function parseFromHeader(fromText = "") {
  // Examples:
  // 1) "\"Emily Kuo\" <emilykuo@cpp.edu>"
  // 2) "Emily Kuo <emilykuo@cpp.edu>"
  // 3) "<emilykuo@cpp.edu>"
  // 4) "emilykuo@cpp.edu"

  const emailMatch = fromText.match(/<([^>]+)>/);
  const email = emailMatch ? emailMatch[1].trim() : (fromText.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0] || "");

  // Name is anything before <email>, remove quotes/spaces
  let name = "";
  if (emailMatch) {
    name = fromText.slice(0, emailMatch.index).trim();
  } else {
    // If no <...>, name might not exist
    name = "";
  }

  name = name.replace(/^"+|"+$/g, "").trim(); // remove surrounding quotes
  return { name, email };
}

function normalizeBodyText(text = "") {
  // Basic cleanup: trim, normalize line endings, remove excess blank lines
  return String(text)
    .replace(/\r\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

return items.map((item) => {
  const data = item.json || {};

  // 1) Best source: Gmail trigger "from.value[0]"
  const fromObj = data.from?.value?.[0];
  let senderName = fromObj?.name?.trim() || "";
  let senderEmail = fromObj?.address?.trim() || "";

  // 2) Fallback: parse from "from.text"
  if (!senderEmail) {
    const parsed = parseFromHeader(data.from?.text || "");
    senderName = senderName || parsed.name;
    senderEmail = senderEmail || parsed.email;
  }

  // 3) Fallback: parse from headers["from"]
  if (!senderEmail) {
    const headerFrom = data.headers?.from || data.headers?.From || "";
    const parsed = parseFromHeader(headerFrom);
    senderName = senderName || parsed.name;
    senderEmail = senderEmail || parsed.email;
  }

  // Body text: prefer plain text field
  let bodyText = normalizeBodyText(data.text || "");

  // Fallback to stripping HTML if text is missing
  if (!bodyText && data.html) {
    // crude HTML -> text (good enough for MVP)
    bodyText = normalizeBodyText(
      String(data.html)
        .replace(/<style[\s\S]*?<\/style>/gi, "")
        .replace(/<script[\s\S]*?<\/script>/gi, "")
        .replace(/<\/(div|p|br|li|tr|h1|h2|h3|h4|h5|h6)>/gi, "\n")
        .replace(/<[^>]+>/g, " ")
        .replace(/&nbsp;/g, " ")
        .replace(/&amp;/g, "&")
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .replace(/&quot;/g, "\"")
        .replace(/&#39;/g, "'")
    );
  }

  return {
    json: {
      senderName,
      senderEmail,
      bodyText,
      // Optional useful extras (keep or delete)
      subject: data.subject || data.headers?.subject || "",
      messageId: data.messageId || "",
      threadId: data.threadId || data.id || "",
    },
  };
});

const baseUrl = 'https://YOUR_N8N_HOST/webhook/odi-feedback';

const threadId = $('Code in JavaScript').item.json.threadId;
const email = $('Code in JavaScript').item.json.senderEmail;

function feedbackUrl(rating) {
  return `${baseUrl}?thread_id=${encodeURIComponent(threadId)}&email=${encodeURIComponent(email)}&rating=${rating}`;
}

// Convert the LLM's plain text email into safe HTML
function escapeHtml(text) {
  return String(text)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

const emailBodyHtml = escapeHtml($('generateEmail').item.json.output).replace(/\n/g, "<br>");

const feedbackBlock = `
<br><br>
<hr style="border:none;border-top:1px solid #ddd;margin:24px 0;">
<div style="font-family:Arial, sans-serif; font-size:14px; line-height:1.5;">
  <p style="margin:0 0 8px 0;"><strong>How helpful was this product recommendation?</strong></p>
  <p style="margin:0 0 12px 0; color:#555;">Click a star to rate your experience.</p>

  <div style="font-size:28px; letter-spacing:4px; line-height:1.4;">
    <a href="${feedbackUrl(1)}" style="text-decoration:none; color:#f5a623;">&#9733;</a>
    <a href="${feedbackUrl(2)}" style="text-decoration:none; color:#f5a623;">&#9733;</a>
    <a href="${feedbackUrl(3)}" style="text-decoration:none; color:#f5a623;">&#9733;</a>
    <a href="${feedbackUrl(4)}" style="text-decoration:none; color:#f5a623;">&#9733;</a>
    <a href="${feedbackUrl(5)}" style="text-decoration:none; color:#f5a623;">&#9733;</a>
  </div>

  <p style="margin:8px 0 0 0; font-size:12px; color:#777;">
    1 = Not helpful, 5 = Very helpful
  </p>
</div>
`;

return [
  {
    json: {
      finalEmailHtml: emailBodyHtml + feedbackBlock
    }
  }
];
